-- | Mirrors the record @main@ reads and writes (bin/acp-dispatch:5130).
data MainRecord = MainRecord
  { mainRecordMain :: Bool
  , mainRecordPath :: Bool
  , mainRecordHead :: Int
  } deriving (Show, Eq)

defaultMainRecord :: MainRecord
defaultMainRecord = MainRecord
  { mainRecordMain = False
  , mainRecordPath = False
  , mainRecordHead = 0
  }

decodeMainRecord :: Fields -> Either String MainRecord
decodeMainRecord kv =
  MainRecord
    <$> fieldBool "main" kv
    <*> fieldBool "path" kv
    <*> fieldInt "head" kv

encodeMainRecord :: MainRecord -> Fields
encodeMainRecord r =
  [ ("main", encBool (mainRecordMain r))
  , ("path", encBool (mainRecordPath r))
  , ("head", encInt (mainRecordHead r))
  ]

mainRecordMainL :: Lens' MainRecord (Bool)
mainRecordMainL k r = (\v -> r { mainRecordMain = v }) <$> k (mainRecordMain r)
{-# INLINE mainRecordMainL #-}

mainRecordPathL :: Lens' MainRecord (Bool)
mainRecordPathL k r = (\v -> r { mainRecordPath = v }) <$> k (mainRecordPath r)
{-# INLINE mainRecordPathL #-}

mainRecordHeadL :: Lens' MainRecord (Int)
mainRecordHeadL k r = (\v -> r { mainRecordHead = v }) <$> k (mainRecordHead r)
{-# INLINE mainRecordHeadL #-}

